import Qs from 'qs'

function firstString(value: unknown): string | undefined {
  if (typeof value === 'string') return value
  if (Array.isArray(value)) {
    for (const item of value) {
      if (typeof item === 'string') return item
    }
  }
  return undefined
}

// Google 回调可能把 token 追加在 #/ 后，不能只解析含 ? 的 hash。
// 与新项目保持一致：hash 优先，未命中时回退 search。
export default function getGoogleCallbackToken(): string | undefined {
  if (typeof window === 'undefined') return undefined
  const { hash, search } = window.location
  const questionMarkAt = hash.indexOf('?')
  const hashQuery = questionMarkAt !== -1 ? hash.slice(questionMarkAt + 1) : hash.slice(1)
  const fromHash = firstString(Qs.parse(hashQuery).token)
  if (fromHash !== undefined) return fromHash
  return firstString(Qs.parse(search, { ignoreQueryPrefix: true }).token)
}
